def image(name):
    p=(REVIEW/name) if name.startswith('pdf') else (ASSETS/name)
    mime='image/png' if p.suffix=='.png' else 'image/jpeg'
    return 'data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()

