def link(url,label,cls='text-link'):
    return f'<a class="{cls}" href="{html.escape(url,quote=True)}" target="_blank" rel="noopener noreferrer">{label}</a>'

def snippet(rel,a,b,label,url):
    ls=(REVIEW/rel).read_text(encoding='utf-8-sig').splitlines()
    code='\n'.join(ls[a-1:b])
    return f'<details class="code"><summary>{label}</summary><pre><code>{html.escape(code)}</code></pre><div class="code-foot">{link(url,"전체 코드 보기")}</div></details>'

